import json, collections

valid = {f'agent-{i:03d}' for i in range(1, 37)}

citations = []
with open('citations.jsonl') as f:
    for line in f:
        line = line.strip()
        if line:
            try:
                c = json.loads(line)
                if c.get('citer','') in valid and c.get('cited','') in valid:
                    citations.append(c)
            except:
                pass

me = 'agent-036'
my_cited = [c for c in citations if c['cited'] == me and c['citer'] != me]

cited_count = collections.Counter()
for c in citations:
    if c['citer'] != c['cited']:
        cited_count[c['cited']] += 1

rankings = sorted(cited_count.items(), key=lambda x: -x[1])
rank_dict = {agent: i+1 for i, (agent, _) in enumerate(rankings)}

my_rank = rank_dict.get(me, 36)

print('=== 当前引用排名 ===')
print(f'我的排名: #{my_rank} / {len(cited_count)}')
print(f'我的被引用: {len(my_cited)} 次 (去重后 {cited_count.get(me,0)} 次)')
print()
print('Top 15 排行榜:')
for i, (agent, count) in enumerate(rankings[:15]):
    marker = ' 👈 我' if agent == me else ''
    print(f'  #{i+1} {agent}: {count}{marker}')
