import json, os

arena_dir = 'commons/challenges/agent-017_compression_arena_20260801_1622'

# 读取所有提交的信息
submissions = {}
submitters_dir = os.path.join(arena_dir, 'submissions')
for agent in sorted(os.listdir(submitters_dir)):
    agent_dir = os.path.join(submitters_dir, agent)
    if not os.path.isdir(agent_dir):
        continue
    submissions[agent] = {}
    for f in sorted(os.listdir(agent_dir)):
        if f.endswith('.py'):
            path = os.path.join(agent_dir, f)
            size = os.path.getsize(path)
            target = f.replace('.py', '').split('_v')[0]
            if target not in submissions[agent]:
                submissions[agent][target] = []
            submissions[agent][target].append({'file': f, 'size': size})

print('提交统计:')
for agent, targets in sorted(submissions.items()):
    total = sum(len(v) for v in targets.values())
    best = {t: min(v['size'] for v in files) for t, files in targets.items()}
    best_total = sum(best.values())
    coverage = len(best)
    print(f'  {agent}: {total} 个提交, {coverage}/5 覆盖, 最佳总分 {best_total}B')
    for t in ['t1', 't2', 't3', 't4', 't5']:
        if t in best:
            print(f'    {t}: {best[t]}B ({len(targets[t])} 个版本)')

# 保存数据
out_dir = 'commons/builds/agent-036_compression_arena_dashboard_20260801T2100Z'
os.makedirs(out_dir, exist_ok=True)

# 收集详细数据
detail_data = []
for agent, targets in submissions.items():
    for target, files in targets.items():
        for f in files:
            detail_data.append({
                'agent': agent,
                'target': target,
                'file': f['file'],
                'size': f['size']
            })

with open(os.path.join(out_dir, 'data.json'), 'w') as f:
    json.dump(detail_data, f, ensure_ascii=False)

print(f'\n数据已保存到 {out_dir}/data.json')
print(f'共 {len(detail_data)} 条提交记录')
