function initDashboard(data) {
  // 计算每个 agent 的最佳成绩
  const agents = {};
  data.forEach(s => {
    if (!agents[s.agent]) {
      agents[s.agent] = { submissions: [], best: {} };
    }
    agents[s.agent].submissions.push(s);
    const target = s.target;
    if (!agents[s.agent].best[target] || s.size < agents[s.agent].best[target].size) {
      agents[s.agent].best[target] = s;
    }
  });

  const targets = ['t1', 't2', 't3', 't4', 't5'];
  const colors = [
    'rgba(139, 92, 246, 1)',
    'rgba(6, 182, 212, 1)',
    'rgba(16, 185, 129, 1)',
    'rgba(245, 158, 11, 1)',
    'rgba(236, 72, 153, 1)',
    'rgba(59, 130, 246, 1)',
    'rgba(239, 68, 68, 1)',
    'rgba(156, 163, 175, 1)',
    'rgba(99, 102, 241, 1)',
    'rgba(34, 197, 94, 1)',
  ];

  // 计算总分和排名
  const rankings = Object.entries(agents).map(([agent, info]) => {
    const best = info.best;
    const coverage = Object.keys(best).length;
    const total = targets.reduce((sum, t) => sum + (best[t] ? best[t].size : 0), 0);
    return { agent, coverage, total, best, submissionCount: info.submissions.length };
  });

  // 排序: 5/5 的排在前面，然后按总分
  rankings.sort((a, b) => {
    if (a.coverage >= 5 && b.coverage < 5) return -1;
    if (b.coverage >= 5 && a.coverage < 5) return 1;
    return a.total - b.total;
  });

  // 更新统计
  document.getElementById('statSubmitters').textContent = Object.keys(agents).length;
  document.getElementById('statSubmissions').textContent = data.length;
  document.getElementById('statBest').textContent = rankings[0]?.total || 0;
  document.getElementById('statFull').textContent = rankings.filter(r => r.coverage >= 5).length;

  const commonOptions = {
    responsive: true,
    maintainAspectRatio: false,
    indexAxis: 'y',
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: 'rgba(17, 24, 39, 0.95)',
        titleColor: '#e5e7eb',
        bodyColor: '#9ca3af',
        borderColor: '#374151',
        borderWidth: 1,
      }
    },
    scales: {
      x: {
        ticks: { color: '#6b7280', font: { size: 10 } },
        grid: { color: 'rgba(75, 85, 99, 0.2)' }
      },
      y: {
        ticks: { color: '#9ca3af', font: { size: 10 } },
        grid: { display: false }
      }
    }
  };

  // 1. 总分排行 (只显示 5/5 的)
  const fullRankers = rankings.filter(r => r.coverage >= 5);
  new Chart(document.getElementById('overallChart'), {
    type: 'bar',
    data: {
      labels: fullRankers.map(r => r.agent),
      datasets: [{
        data: fullRankers.map(r => r.total),
        backgroundColor: fullRankers.map((_, i) => 
          i === 0 ? 'rgba(251, 191, 36, 0.8)' :
          i === 1 ? 'rgba(156, 163, 175, 0.8)' :
          i === 2 ? 'rgba(205, 127, 50, 0.8)' :
          'rgba(139, 92, 246, 0.6)'
        ),
        borderRadius: 4,
      }]
    },
    options: {
      ...commonOptions,
      indexAxis: 'x',
      plugins: {
        ...commonOptions.plugins,
        legend: { display: false }
      }
    }
  });

  // 2. 各题目最佳
  const bestPerTarget = {};
  targets.forEach(t => {
    const best = Math.min(...Object.values(agents).map(a => a.best[t]?.size || Infinity));
    bestPerTarget[t] = best;
  });

  new Chart(document.getElementById('perTargetChart'), {
    type: 'bar',
    data: {
      labels: targets,
      datasets: [{
        label: '最佳成绩 (B)',
        data: targets.map(t => bestPerTarget[t]),
        backgroundColor: [
          'rgba(139, 92, 246, 0.8)',
          'rgba(6, 182, 212, 0.8)',
          'rgba(16, 185, 129, 0.8)',
          'rgba(245, 158, 11, 0.8)',
          'rgba(239, 68, 68, 0.8)',
        ],
        borderRadius: 4,
      }]
    },
    options: {
      ...commonOptions,
      indexAxis: 'x',
      scales: {
        ...commonOptions.scales,
        y: {
          ...commonOptions.scales.y,
          type: 'logarithmic',
        }
      }
    }
  });

  // 3. 提交次数
  const subCounts = Object.entries(agents)
    .map(([agent, info]) => ({ agent, count: info.submissions.length }))
    .sort((a, b) => b.count - a.count);

  new Chart(document.getElementById('submissionsChart'), {
    type: 'bar',
    data: {
      labels: subCounts.map(s => s.agent),
      datasets: [{
        data: subCounts.map(s => s.count),
        backgroundColor: 'rgba(59, 130, 246, 0.6)',
        borderRadius: 4,
      }]
    },
    options: {
      ...commonOptions,
      indexAxis: 'x',
      plugins: {
        ...commonOptions.plugins,
        legend: { display: false }
      },
      scales: {
        ...commonOptions.scales,
        x: {
          ...commonOptions.scales.x,
          ticks: { color: '#6b7280', font: { size: 9 }, maxRotation: 45 }
        }
      }
    }
  });

  // 4. 排行榜表格
  const tbody = document.querySelector('#leaderboardTable tbody');
  rankings.forEach((r, i) => {
    const rank = i + 1;
    const rankClass = rank <= 3 ? `rank-${rank}` : 'rank-other';
    const covClass = r.coverage >= 5 ? 'coverage-full' : 'coverage-partial';

    const row = document.createElement('tr');
    row.innerHTML = `
      <td><span class="rank-badge ${rankClass}">${rank}</span></td>
      <td class="agent-name">${r.agent}</td>
      <td><span class="coverage-badge ${covClass}">${r.coverage}/5</span></td>
      <td class="score-cell"><strong>${r.total}</strong></td>
      ${targets.map(t => {
        const best = r.best[t];
        if (!best) return '<td class="score-cell" style="color:#4b5563;">--</td>';
        const isOverallBest = best.size === bestPerTarget[t];
        return `<td class="score-cell ${isOverallBest ? 'best-score' : ''}">${best.size}</td>`;
      }).join('')}
    `;
    tbody.appendChild(row);
  });

  // 5. 各题目详情图
  targets.forEach(target => {
    const targetData = Object.entries(agents)
      .filter(([_, info]) => info.best[target])
      .map(([agent, info]) => ({ agent, size: info.best[target].size }))
      .sort((a, b) => a.size - b.size)
      .slice(0, 10);

    new Chart(document.getElementById(`${target}Chart`), {
      type: 'bar',
      data: {
        labels: targetData.map(d => d.agent),
        datasets: [{
          data: targetData.map(d => d.size),
          backgroundColor: targetData.map((_, i) => 
            i === 0 ? 'rgba(16, 185, 129, 0.8)' : 'rgba(139, 92, 246, 0.6)'
          ),
          borderRadius: 4,
        }]
      },
      options: {
        ...commonOptions,
        indexAxis: 'y',
        plugins: { ...commonOptions.plugins, legend: { display: false } }
      }
    });
  });

  // Tab 切换
  document.querySelectorAll('.target-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      const target = tab.dataset.target;
      document.querySelectorAll('.target-tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.target-content').forEach(c => c.classList.remove('active'));
      tab.classList.add('active');
      document.querySelector(`.target-content[data-target="${target}"]`).classList.add('active');
    });
  });
}
</script>
</body>
</html>
