function initChallengeHub(challenges) {
  const grid = document.getElementById('challengesGrid');
  const hotList = document.getElementById('hotList');

  // 按活跃度排序（有 submitters 的排前面）
  const sorted = [...challenges].sort((a, b) => {
    const aScore = (a.submitters || 0) * 10 + (a.submissions || 0);
    const bScore = (b.submitters || 0) * 10 + (b.submissions || 0);
    return bScore - aScore;
  });

  // 更新统计
  document.getElementById('statTotal').textContent = challenges.length;
  document.getElementById('statArenas').textContent = challenges.filter(c => c.type === 'arena').length;
  document.getElementById('statMarkdown').textContent = challenges.filter(c => c.type === 'markdown').length;

  // 热门挑战 Top 5
  const top5 = sorted.filter(c => c.submitters > 0).slice(0, 5);
  top5.forEach((c, i) => {
    const item = document.createElement('div');
    item.className = 'hot-item';
    item.innerHTML = `
      <div class="rank">${i + 1}</div>
      <div class="info">
        <h4>${c.name}</h4>
        <div class="meta">${c.author || '未知'} · ${c.type === 'arena' ? '竞技场' : '主题挑战'}</div>
      </div>
      <div class="count">${c.submitters} 人参赛</div>
    `;
    hotList.appendChild(item);
  });

  // 渲染所有挑战卡片
  function renderChallenges(filter = 'all', search = '') {
    grid.innerHTML = '';
    let filtered = challenges;

    if (filter === 'arena') {
      filtered = challenges.filter(c => c.type === 'arena');
    } else if (filter === 'markdown') {
      filtered = challenges.filter(c => c.type === 'markdown');
    } else if (filter === 'hot') {
      filtered = challenges.filter(c => c.submitters > 0).sort((a, b) => (b.submitters || 0) - (a.submitters || 0));
    }

    if (search) {
      const q = search.toLowerCase();
      filtered = filtered.filter(c =>
        c.name.toLowerCase().includes(q) ||
        (c.description || '').toLowerCase().includes(q) ||
        (c.author || '').toLowerCase().includes(q)
      );
    }

    // 按活跃度排序
    filtered.sort((a, b) => {
      const aScore = (a.submitters || 0) * 100 + (a.submissions || 0);
      const bScore = (b.submitters || 0) * 100 + (b.submissions || 0);
      return bScore - aScore;
    });

    filtered.forEach(c => {
      const badgeClass = c.type === 'arena' ? 'arena' : (c.type === 'markdown' ? 'markdown' : 'other');
      const badgeText = c.type === 'arena' ? '竞技场' : (c.type === 'markdown' ? '挑战' : '其他');

      const card = document.createElement('div');
      card.className = 'challenge-card';
      card.dataset.type = c.type;

      let statsHtml = '';
      if (c.submitters) {
        statsHtml = `
          <div class="challenge-stats">
            <div class="challenge-stat">
              <div class="stat-value">${c.submitters}</div>
              <div class="stat-label">参赛者</div>
            </div>
            <div class="challenge-stat">
              <div class="stat-value">${c.submissions}</div>
              <div class="stat-label">提交数</div>
            </div>
          </div>
        `;
      } else {
        statsHtml = `
          <div class="challenge-stats">
            <div class="challenge-stat" style="flex:1;">
              <div class="stat-value" style="font-size:0.9rem;color:var(--text-dim);">等待参与者</div>
              <div class="stat-label">快来成为第一个！</div>
            </div>
          </div>
        `;
      }

      card.innerHTML = `
        <span class="badge ${badgeClass}">${badgeText}</span>
        <div class="author">${c.author || '未知作者'}</div>
        <h3>${c.name}</h3>
        <div class="description">${c.description || ''}...</div>
        ${statsHtml}
      `;

      grid.appendChild(card);
    });
  }

  renderChallenges();

  // 过滤按钮
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      renderChallenges(btn.dataset.filter, document.getElementById('searchBox').value);
    });
  });

  // 搜索
  document.getElementById('searchBox').addEventListener('input', (e) => {
    const activeFilter = document.querySelector('.filter-btn.active').dataset.filter;
    renderChallenges(activeFilter, e.target.value);
  });
}
</script>
