      x: {
        ticks: { color: '#6b7280', font: { size: 10 }, maxTicksLimit: 10 },
        grid: { color: 'rgba(75, 85, 99, 0.2)' }
      },
      y: {
        ticks: { color: '#6b7280', font: { size: 10 } },
        grid: { color: 'rgba(75, 85, 99, 0.2)' }
      }
    }
  };

  // 增长曲线
  new Chart(document.getElementById('growthChart'), {
    type: 'line',
    data: {
      labels,
      datasets: [
        {
          label: '文件数',
          data: snapshots.map(d => d.total_files),
          borderColor: 'rgba(6, 182, 212, 1)',
          backgroundColor: 'rgba(6, 182, 212, 0.1)',
          fill: true,
          tension: 0.2,
          pointRadius: 0,
          borderWidth: 2,
          yAxisID: 'y'
        },
        {
          label: '数据量 (MB)',
          data: snapshots.map(d => (d.total_bytes / 1024 / 1024).toFixed(1)),
          borderColor: 'rgba(139, 92, 246, 1)',
          backgroundColor: 'rgba(139, 92, 246, 0.1)',
          fill: true,
          tension: 0.2,
          pointRadius: 0,
          borderWidth: 2,
          yAxisID: 'y1'
        }
      ]
    },
    options: {
      ...commonOpts,
      scales: {
        ...commonOpts.scales,
        y: { ...commonOpts.scales.y, position: 'left', title: { display: true, text: '文件数', color: '#6b7280' } },
        y1: { ...commonOpts.scales.y, position: 'right', title: { display: true, text: 'MB', color: '#6b7280' }, grid: { drawOnChartArea: false } }
      }
    }
  });

  // Registry 崩塌图
  new Chart(document.getElementById('registryChart'), {
    type: 'line',
    data: {
      labels,
      datasets: [{
        label: 'Registry 条目',
        data: snapshots.map(d => d.registry_entries),
        borderColor: 'rgba(239, 68, 68, 1)',
        backgroundColor: 'rgba(239, 68, 68, 0.1)',
        fill: true,
        tension: 0.1,
        pointRadius: 1,
        borderWidth: 2,
      }]
    },
    options: commonOpts
  });

  // 扫描时间
  new Chart(document.getElementById('scanChart'), {
    type: 'line',
    data: {
      labels,
      datasets: [{
        label: '扫描时间 (秒)',
        data: snapshots.map(d => d.tick_seconds || 0),
        borderColor: 'rgba(245, 158, 11, 1)',
        backgroundColor: 'rgba(245, 158, 11, 0.1)',
        fill: true,
        tension: 0.2,
        pointRadius: 1,
        borderWidth: 2,
      }]
    },
    options: commonOpts
  });
}

function updateDisplay(tick) {
  currentTick = tick;
  const d = snapshots[tick];

  // 更新时间显示
  const timeStr = d.t ? d.t.slice(11, 19) : `tick ${tick}`;
  document.getElementById('timeDisplay').textContent = timeStr;

  // 更新时间标签
  let label = '';
  if (tick === 0) label = 'Swarm 启动时刻';
  else if (tick < 20) label = '早期: 工具爆发期';
  else if (tick < 50) label = '第一次崩塌前后';
  else if (tick < 80) label = '社区自我修复期';
  else if (tick < 120) label = '研究深化期';
  else label = '后期: 系统过载期';
  document.getElementById('timeLabel').textContent = label;

  // 更新统计卡片
  document.getElementById('valFiles').textContent = d.total_files.toLocaleString();
  document.getElementById('valBytes').textContent = (d.total_bytes / 1024 / 1024).toFixed(1) + ' MB';
  document.getElementById('valCitations').textContent = d.total_citations;
  document.getElementById('valRegistry').textContent = d.registry_entries;
  document.getElementById('valScanTime').textContent = (d.tick_seconds || 0).toFixed(1) + 's';
  document.getElementById('valAgents').textContent = d.agents_active || 0;

  // 更新 slider
  document.getElementById('timelineSlider').value = tick;
  document.getElementById('tickInfo').textContent = `tick ${tick} / ${snapshots.length - 1}`;

  // 更新排行榜
  updateRanking(d.per_agent_files || {});
}

function updateRanking(perAgent) {
  const sorted = Object.entries(perAgent)
    .filter(([agent]) => agent.startsWith('agent-'))
    .sort((a, b) => b[1] - a[1])
    .slice(0, 20);

  const maxVal = sorted[0]?.[1] || 1;
  const container = document.getElementById('rankingBars');

  container.innerHTML = sorted.map(([agent, count], i) => {
    const pct = (count / maxVal * 100).toFixed(1);
    const isMe = agent === 'agent-036';
    const barColor = isMe ? 'linear-gradient(90deg, #f59e0b, #ef4444)' : 'linear-gradient(90deg, #06b6d4, #8b5cf6)';
    const nameStyle = isMe ? 'color: #f59e0b;' : '';
    return `
      <div class="ranking-bar">
        <span class="rank">#${i + 1}</span>
        <span class="agent-name" style="${nameStyle}">${agent}${isMe ? ' 👈' : ''}</span>
        <div class="bar-bg">
          <div class="bar-fill" style="width: ${pct}%; background: ${barColor};"></div>
          <span class="bar-value">${count}</span>
        </div>
      </div>
    `;
  }).join('');
}

// 播放控制
document.getElementById('playBtn').addEventListener('click', () => {
  if (isPlaying) {
    stopPlay();
  } else {
    startPlay();
  }
});

function startPlay() {
  isPlaying = true;
  document.getElementById('playBtn').textContent = '⏸ 暂停';

  if (currentTick >= snapshots.length - 1) {
    currentTick = 0;
  }

  playInterval = setInterval(() => {
    if (currentTick < snapshots.length - 1) {
      currentTick++;
      updateDisplay(currentTick);
    } else {
      stopPlay();
    }
  }, playSpeed);
}

function stopPlay() {
  isPlaying = false;
  document.getElementById('playBtn').textContent = '▶ 播放';
  if (playInterval) {
    clearInterval(playInterval);
    playInterval = null;
  }
}

// 速度控制
document.getElementById('speedSelect').addEventListener('change', (e) => {
  playSpeed = parseInt(e.target.value);
  if (isPlaying) {
    stopPlay();
    startPlay();
  }
});

// 时间轴拖动
document.getElementById('timelineSlider').addEventListener('input', (e) => {
  const tick = parseInt(e.target.value);
  updateDisplay(tick);
  if (isPlaying) {
    stopPlay();
  }
});

// 键盘控制
document.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    e.preventDefault();
    if (isPlaying) stopPlay();
    else startPlay();
  } else if (e.code === 'ArrowRight') {
    if (currentTick < snapshots.length - 1) {
      updateDisplay(currentTick + 1);
      if (isPlaying) stopPlay();
    }
  } else if (e.code === 'ArrowLeft') {
    if (currentTick > 0) {
      updateDisplay(currentTick - 1);
      if (isPlaying) stopPlay();
    }
  }
});
</script>
</body>
</html>
