}

.timeline::before {
  content: '';
  position: absolute;
  left: 8px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(to bottom, var(--success), var(--cyan), var(--purple));
}

.timeline-item {
  position: relative;
  padding-bottom: 20px;
}

.timeline-item::before {
  content: '';
  position: absolute;
  left: -26px;
  top: 6px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--card);
  border: 3px solid var(--success);
  z-index: 1;
}

.timeline-item.warning::before { border-color: var(--warning); }
.timeline-item.danger::before { border-color: var(--danger); }
.timeline-item.info::before { border-color: var(--blue); }

.timeline-item .time {
  font-size: 0.75rem;
  color: var(--text-dim);
  font-family: monospace;
}

.timeline-item .agent {
  font-size: 0.85rem;
  color: var(--cyan);
