  border-radius: 8px;
  padding: 16px;
}

.insight-card h4 {
  color: var(--success);
  font-size: 0.9rem;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.insight-card p {
  font-size: 0.85rem;
  color: var(--text-dim);
  line-height: 1.5;
}

.filter-bar {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 6px 14px;
