</div>

<script>
let corrections = [];

fetch('corrections.json')
  .then(r => r.json())
  .then(data => {
    corrections = data;
    initDashboard(data);
  });

function initDashboard(data) {
  const commonOpts = {
    responsive: true,
    maintainAspectRatio: false,
    indexAxis: 'y',
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: 'rgba(17, 24, 39, 0.95)',
        titleColor: '#e5e7eb',
        bodyColor: '#9ca3af',
        borderColor: '#374151',
        borderWidth: 1,
      }
    },
    scales: {
      x: {
        ticks: { color: '#6b7280', font: { size: 10 } },
        grid: { color: 'rgba(75, 85, 99, 0.2)' }
      },
      y: {
        ticks: { color: '#9ca3af', font: { size: 10 } },
        grid: { display: false }
      }
    }
  };

  // 按 agent 统计
  const byAgent = {};
  data.forEach(d => {
    const agent = d.from || 'unknown';
    byAgent[agent] = (byAgent[agent] || 0) + 1;
  });

  const sortedAgents = Object.entries(byAgent)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 15);

  new Chart(document.getElementById('byAgentChart'), {
    type: 'bar',
    data: {
      labels: sortedAgents.map(d => d[0]),
      datasets: [{
        data: sortedAgents.map(d => d[1]),
        backgroundColor: sortedAgents.map((_, i) => 
          i === 0 ? 'rgba(16, 185, 129, 0.9)' :
          i === 1 ? 'rgba(6, 182, 212, 0.8)' :
          i === 2 ? 'rgba(139, 92, 246, 0.7)' :
          'rgba(107, 114, 128, 0.6)'
        ),
        borderRadius: 4,
      }]
    },
    options: commonOpts
  });

  // 时间分布（按小时）
  const hourly = {};
  data.forEach(d => {
    if (d.time) {
      const hour = d.time.slice(11, 13);
      hourly[hour] = (hourly[hour] || 0) + 1;
    }
  });

  const hours = Object.keys(hourly).sort();
  new Chart(document.getElementById('overTimeChart'), {
    type: 'line',
    data: {
      labels: hours.map(h => `${h}:00`),
      datasets: [{
        label: '修正事件数',
        data: hours.map(h => hourly[h]),
        borderColor: 'rgba(16, 185, 129, 1)',
        backgroundColor: 'rgba(16, 185, 129, 0.1)',
        fill: true,
        tension: 0.3,
        pointRadius: 4,
        pointBackgroundColor: 'rgba(16, 185, 129, 1)',
      }]
    },
    options: {
      ...commonOpts,
      indexAxis: 'x',
      scales: {
        ...commonOpts.scales,
        y: { ...commonOpts.scales.y, beginAtZero: true }
      }
    }
  });

  // 渲染时间线
  renderTimeline(data, 'all');

  // 过滤按钮
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      renderTimeline(data, btn.dataset.filter);
    });
  });
}

function renderTimeline(data, filter) {
  const timeline = document.getElementById('timeline');

  let filtered = data;
  if (filter !== 'all') {
    const keywords = {
      registry: ['registry', '注册', '崩塌', 'collapse'],
      correction: ['self-correct', 'self correct', 'correction', '我错了', '修正', '更正', 'retract', '撤回', 'wrong', '推翻'],
      security: ['security', '安全', 'secret', 'sentry', 'guard', 'bug', '漏洞', 'vulnerability'],
      science: ['hypothesis', '假设', 'falsif', '证伪', 'replication', '复制', 'null model', '零模型', 'p-value']
    };
    const kws = keywords[filter] || [];
    filtered = data.filter(d => {
      const msg = d.message.toLowerCase();
      return kws.some(kw => msg.includes(kw.toLowerCase()));
    });
  }

  // 只显示最近的 30 条，避免页面太长
  const display = filtered.slice(-30).reverse();

  timeline.innerHTML = display.map(d => {
    const msg = d.message.slice(0, 150);
    const hasMore = d.message.length > 150;
    const time = d.time ? d.time.slice(11, 19) : '';
    const agent = d.from || 'unknown';

    // 分类
    let typeClass = '';
    const lower = d.message.toLowerCase();
    if (lower.includes('urgent') || lower.includes('警报') || lower.includes('严重')) {
      typeClass = 'danger';
    } else if (lower.includes('self-correct') || lower.includes('我错了') || lower.includes('correction') || lower.includes('修正')) {
      typeClass = 'info';
    } else if (lower.includes('fix') || lower.includes('修复') || lower.includes('bug')) {
      typeClass = 'warning';
    }

    return `
      <div class="timeline-item ${typeClass}">
        <span class="time">${time}</span>
        <div class="agent">${agent}</div>
        <p>${msg}${hasMore ? '...' : ''}</p>
      </div>
    `;
  }).join('');
}
</script>
