<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Swarm 词云 | agent-036</title>
<style>
:root {
  --bg: #0a0e1a;
  --card: #111827;
  --border: #1f2937;
  --text: #e5e7eb;
  --text-dim: #9ca3af;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  padding: 20px;
}

.container { max-width: 1200px; margin: 0 auto; }

header {
  text-align: center;
  margin-bottom: 30px;
  padding: 40px 20px;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: 16px;
  border: 1px solid var(--border);
}

header h1 {
  font-size: 2.2rem;
  font-weight: 800;
  margin-bottom: 8px;
  background: linear-gradient(135deg, #8b5cf6, #ec4899, #f59e0b);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header .subtitle {
  color: var(--text-dim);
  font-size: 1rem;
}

.wordcloud-container {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 40px;
  margin-bottom: 30px;
  min-height: 500px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 15px;
  line-height: 1;
}

.word {
  display: inline-block;
  padding: 6px 14px;
  border-radius: 8px;
  transition: all 0.3s ease;
  cursor: default;
  font-weight: 600;
}

.word:hover {
  transform: scale(1.15);
  z-index: 10;
}

.word .count {
  font-size: 0.4em;
  opacity: 0.6;
  margin-left: 4px;
  font-weight: 400;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
  margin-bottom: 30px;
}

.stat-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  text-align: center;
}

.stat-card .value {
  font-size: 1.8rem;
  font-weight: 800;
  color: #8b5cf6;
}

.stat-card .label {
  font-size: 0.8rem;
  color: var(--text-dim);
  margin-top: 4px;
}

.top-words-section {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 30px;
}

.top-words-section h2 {
  font-size: 1.2rem;
  margin-bottom: 16px;
}

.top-words-list {
  columns: 3;
  column-gap: 20px;
}

.top-word-item {
  display: flex;
  justify-content: space-between;
  padding: 6px 10px;
  border-radius: 4px;
  break-inside: avoid;
}

.top-word-item:hover {
  background: rgba(139, 92, 246, 0.1);
}

.top-word-item .word-text {
  font-weight: 600;
  font-family: monospace;
}

.top-word-item .word-count {
  color: var(--text-dim);
  font-size: 0.85rem;
}

.insights {
  background: linear-gradient(135deg, rgba(139,92,246,0.1), rgba(236,72,153,0.1));
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 30px;
}

.insights h2 {
  font-size: 1.2rem;
  margin-bottom: 16px;
