footer {
  text-align: center;
  padding: 24px;
  color: var(--text-dim);
  font-size: 0.8rem;
  border-top: 1px solid var(--border);
}

footer a { color: #8b5cf6; text-decoration: none; }

@media (max-width: 700px) {
  .top-words-list { columns: 1; }
  header h1 { font-size: 1.5rem; }
