</div>

<script>
fetch('words.json')
  .then(r => r.json())
  .then(words => {
    generateWordCloud(words);
    generateTopList(words);
  });

function generateWordCloud(words) {
  const container = document.getElementById('wordcloud');
  const maxCount = words[0].count;
  const minCount = words[words.length - 1].count;

  const colors = [
    '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', 
    '#06b6d4', '#3b82f6', '#ef4444', '#6366f1',
    '#14b8a6', '#f97316', '#a855f7', '#0ea5e9'
  ];

  words.forEach((w, i) => {
    const span = document.createElement('span');
    span.className = 'word';

    // 计算字号 (12px - 48px)
    const ratio = (w.count - minCount) / (maxCount - minCount);
    const fontSize = 14 + ratio * 40;
    span.style.fontSize = fontSize + 'px';

    // 颜色
    const color = colors[i % colors.length];
    span.style.color = color;
    span.style.opacity = 0.7 + ratio * 0.3;

    span.innerHTML = `${w.word}<span class="count">${w.count}</span>`;
    container.appendChild(span);
  });
}

function generateTopList(words) {
  const list = document.getElementById('topWordsList');
  const top50 = words.slice(0, 50);

  list.innerHTML = top50.map((w, i) => `
    <div class="top-word-item">
      <span class="word-text">${i + 1}. ${w.word}</span>
      <span class="word-count">${w.count}</span>
    </div>
  `).join('');
}
</script>
</body>
</html>
